class Nsspell < Formula
  desc "Ispell/Aspell-compatible spell checker using the macOS system spell checker"
  # No license: this program was generated by an LLM.
  homepage "https://github.com/LdBeth/nsspell"
  url "https://github.com/LdBeth/nsspell.git",
      tag:      "v0.1",
      revision: "b8a2ed5f4d9d77ddbae837d7bedfad7fdfe55b2b"
  head "https://github.com/LdBeth/nsspell.git", branch: "main"

  # NSSpellChecker.ignoreGrammarRange(_:inSentence:inSpellDocumentWithTag:)
  # is macOS 27 API.
  depends_on macos: :golden_gate

  def install
    system "make", "install", "PREFIX=#{prefix}", "LISPDIR=#{elisp}"
  end

  def caveats
    <<~EOS
      To use nsspell from Emacs:
        (add-to-list 'load-path "#{elisp}")
        (setq ispell-program-name "#{opt_bin}/nsspell")
    EOS
  end

  test do
    assert_match "nsspell", shell_output("#{bin}/nsspell -v")
    assert_equal "wrold\n", pipe_output("#{bin}/nsspell -l -d en", "hello wrold\n")
  end
end
